# Игровой цикл

def on_on_update():
    global diff, score
    # Ограничение по бокам
    if player.x < 8:
        player.x = 140
    if player.x > 152:
        player.x = 10
    # Прыжки на платформах
    if player.vy > 0:
        for q in sprites.all_of_kind(SpriteKind.food):
            if player.overlaps_with(q):
                # Батут
                if q.data == "trampoline":
                    player.vy = -350
                else:
                    # Обычные и ломающиеся платформы
                    player.vy = -200
                # Хилка
                if q.data == "heal":
                    info.change_life_by(1)
                    q.destroy()
                # Ломающаяся платформа
                if q.data == "breakable":
                    # исчезает после одного прыжка
                    q.destroy()
    # Скроллинг вверх
    if player.y < 60:
        diff = 60 - player.y
        player.y = 60
        for s in sprites.all_of_kind(SpriteKind.food):
            s.y += diff
            if s.y > 160:
                s.destroy()
                createRandomPlatform(randint(20, 140), 0)
        for g in sprites.all_of_kind(SpriteKind.enemy):
            g.y += diff
            if g.y > 160:
                g.destroy()
        score += diff
        info.set_score(score)
    # Столкновение игрока с врагами
    for h in sprites.all_of_kind(SpriteKind.enemy):
        if player.overlaps_with(h):
            h.destroy()
            info.change_life_by(-1)
            if info.life() <= 0:
                game.over(False, effects.dissolve)
    # Столкновение игрока с пулями врагов
    for b in sprites.all_of_kind(SpriteKind.EnemyProjectile):
        if player.overlaps_with(b):
            b.destroy()
            info.change_life_by(-1)
            if info.life() <= 0:
                game.over(False, effects.dissolve)
    # Столкновение пули игрока с врагами
    for c in sprites.all_of_kind(SpriteKind.PlayerProjectile):
        for j in sprites.all_of_kind(SpriteKind.enemy):
            if c.overlaps_with(j):
                j.destroy()
                c.destroy()
                score += 50
                info.set_score(score)
    # Смерть игрока при падении
    if player.y > 160:
        game.over(False, effects.dissolve)
game.on_update(on_on_update)

# Генерация врагов каждые 2 секунды

def on_update_interval():
    spawnEnemy()
game.on_update_interval(2000, on_update_interval)

# Враги стреляют вниз каждые 1.5 секунды

def on_update_interval2():
    global bullet
    for f in sprites.all_of_kind(SpriteKind.enemy):
        bullet = sprites.create_projectile_from_sprite(img("""
            . 3 .
            3 3 3
            . 3 .
            """), f, 0, 80)
        bullet.set_kind(SpriteKind.EnemyProjectile)
game.on_update_interval(1500, on_update_interval2)
